// @minecraft/server-ui 1.3.0 taklidi. Form yanitlari test tarafindan siraya
// konur; siradaki yoksa "iptal" doner (oyuncunun formu kapatmasi).
const queue = [];

class BaseForm {
  constructor(kind) { this.kind = kind; this.parts = []; }
  title(t) { this.parts.push(["title", t]); return this; }
  body(t) { this.parts.push(["body", t]); return this; }
  button(t) { this.parts.push(["button", t]); return this; }
  textField(label, placeholder, def) { this.parts.push(["textField", label, placeholder, def]); return this; }
  dropdown(label, opts, def) {
    if (!Array.isArray(opts) || !opts.length) throw new TypeError("dropdown: secenek listesi bos");
    this.parts.push(["dropdown", label, opts, def]);
    return this;
  }
  toggle(label, def) { this.parts.push(["toggle", label, def]); return this; }
  slider(label, min, max, step, def) { this.parts.push(["slider", label, min, max, step, def]); return this; }
  show(player) {
    __ui.shown.push({ kind: this.kind, parts: this.parts, player: player && player.name });
    const r = queue.shift();
    return Promise.resolve(r || { canceled: true, cancelationReason: "UserClosed" });
  }
}
class ActionFormData extends BaseForm { constructor() { super("action"); } }
class ModalFormData extends BaseForm { constructor() { super("modal"); } }

const __ui = {
  shown: [],
  queue,
  reply(r) { queue.push(r); },
  reset() { __ui.shown.length = 0; queue.length = 0; },
};

export { ActionFormData, ModalFormData, __ui };
